    #[tokio::test]
    async fn git_object_candidate_enumeration_excludes_committed_base_history() {
        fn git(git_dir: &std::path::Path, args: &[&str], input: Option<&[u8]>) -> String {
            let mut child = Command::new("git")
                .arg("--git-dir")
                .arg(git_dir)
                .args(args)
                .env("GIT_AUTHOR_NAME", "Crab Test")
                .env("GIT_AUTHOR_EMAIL", "crab@example.invalid")
                .env("GIT_COMMITTER_NAME", "Crab Test")
                .env("GIT_COMMITTER_EMAIL", "crab@example.invalid")
                .stdin(if input.is_some() {
                    Stdio::piped()
                } else {
                    Stdio::null()
                })
                .stdout(Stdio::piped())
                .stderr(Stdio::piped())
                .spawn()
                .expect("spawn git");
            if let Some(input) = input {
                child
                    .stdin
                    .take()
                    .expect("piped stdin")
                    .write_all(input)
                    .expect("write git stdin");
            }
            let output = child.wait_with_output().expect("wait for git");
            assert!(
                output.status.success(),
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
            String::from_utf8(output.stdout)
                .expect("git output UTF-8")
                .trim()
                .to_owned()
        }

        let temp = tempfile::tempdir().expect("repository tempdir");
        let git_dir = temp.path().join("repo.git");
        let status = Command::new("git")
            .args(["init", "--bare"])
            .arg(&git_dir)
            .status()
            .expect("initialize repository");
        assert!(status.success());

        let base_blob = git(&git_dir, &["hash-object", "-w", "--stdin"], Some(b"base\n"));
        let base_tree = git(
            &git_dir,
            &["mktree"],
            Some(format!("100644 blob {base_blob}\tfile.txt\n").as_bytes()),
        );
        let base_commit = git(
            &git_dir,
            &["commit-tree", &base_tree],
            Some(b"base commit\n"),
        );
        let new_blob = git(&git_dir, &["hash-object", "-w", "--stdin"], Some(b"new\n"));
        let new_tree = git(
            &git_dir,
            &["mktree"],
            Some(format!("100644 blob {new_blob}\tfile.txt\n").as_bytes()),
        );
        let new_commit = git(
            &git_dir,
            &["commit-tree", &new_tree, "-p", &base_commit],
            Some(b"new commit\n"),
        );

        let relative = enumerate_git_object_candidates(
            Some(git_dir.clone()),
            vec![new_commit.clone()],
            vec![base_commit.clone()],
        )
        .await
        .expect("enumerate relative objects")
        .expect("relative enumeration within cap");
        let full = enumerate_git_object_candidates(Some(git_dir), vec![new_commit], Vec::new())
            .await
            .expect("enumerate full objects")
            .expect("full enumeration within cap");
        let base_commit =
            gix_hash::ObjectId::from_hex(base_commit.as_bytes()).expect("base commit object ID");
        let base_tree =
            gix_hash::ObjectId::from_hex(base_tree.as_bytes()).expect("base tree object ID");
        let base_blob =
            gix_hash::ObjectId::from_hex(base_blob.as_bytes()).expect("base blob object ID");

        assert_eq!(relative.len(), 3);
        assert!(relative.len() < full.len());
        assert!(!relative.contains(&base_commit));
        assert!(!relative.contains(&base_tree));
        assert!(!relative.contains(&base_blob));
    }

