    async fn install_test_metadb_commit_dependencies(
        pipeline: &PushPipeline,
        file_hash: MerkleHash,
        chunks: &[(MerkleHash, u64)],
        placements: &[ChunkPlacement],
    ) {
        pipeline
            .chunk_cache
            .lock()
            .await
            .insert(file_hash, CachedFileChunks::new(chunks.to_vec()));
        let mut origins = pipeline.origin_receipts.lock().await;
        for placement in placements {
            origins.entry(placement.xorb_hash).or_insert_with(|| {
                crab_metadata::receipts::OriginReceipt::new(
                    "canonical-origin".to_owned(),
                    pipeline.router.xorb_path(&placement.xorb_hash).to_string(),
                    placement.xorb_hash.into(),
                    [9; 32],
                    1,
                    Some("test-etag".to_owned()),
                    None,
                )
            });
        }
        drop(origins);
        *pipeline.push_commit_receipt.lock().await = Some(test_push_commit_receipt(1));
    }

