    fn test_shard_with_file(
        file_hash: MerkleHash,
        seed: u64,
    ) -> (Bytes, MerkleHash, Bytes, MerkleHash) {
        let chunk_bytes = format!("remote-only-chunk-{seed}").into_bytes();
        let chunk_hash = compute_data_hash(&chunk_bytes);
        let chunk_len = chunk_bytes.len() as u32;
        let (xorb_bytes, xorb_hash, _) = test_xorb_with_chunks(&[(chunk_hash, chunk_bytes)]);

        let xorb = Arc::new(MDBXorbInfo {
            metadata: XorbChunkSequenceHeader::new(xorb_hash, 1, chunk_len as usize),
            chunks: vec![XorbChunkSequenceEntry::new(chunk_hash, chunk_len, 0)],
        });
        let file = MDBFileInfo {
            metadata: FileDataSequenceHeader::new(file_hash, 1, false, false),
            segments: vec![FileDataSequenceEntry::new(xorb_hash, chunk_len, 0, 1)],
            verification: Vec::new(),
            metadata_ext: None,
        };

        let mut writer = crab_xet::shard::ShardWriter::new();
        writer.add_xorb(xorb).expect("add xorb");
        writer.add_file(file).expect("add file");
        let (bytes, shard_hash) = writer.finalize().expect("finalize shard");
        (Bytes::from(bytes), shard_hash, xorb_bytes, xorb_hash)
    }

    fn test_shard_with_file_chunks(
        file_hash: MerkleHash,
        chunks: &[(MerkleHash, Vec<u8>)],
    ) -> (Bytes, MerkleHash, Bytes, MerkleHash, u64) {
        let (xorb_bytes, xorb_hash, _) = test_xorb_with_chunks(chunks);
        let total_bytes = chunks
            .iter()
            .try_fold(0u64, |acc, (_, data)| acc.checked_add(data.len() as u64))
            .expect("test chunks fit u64");
        let chunk_count = u32::try_from(chunks.len()).expect("test chunk count fits u32");
        let total_bytes_u32 = u32::try_from(total_bytes).expect("test file size fits u32");

        let mut offset = 0u32;
        let mut xorb_entries = Vec::with_capacity(chunks.len());
        for (chunk_hash, data) in chunks {
            let chunk_len = u32::try_from(data.len()).expect("test chunk len fits u32");
            xorb_entries.push(XorbChunkSequenceEntry::new(*chunk_hash, chunk_len, offset));
            offset = offset.checked_add(chunk_len).expect("test offset fits u32");
        }

        let xorb = Arc::new(MDBXorbInfo {
            metadata: XorbChunkSequenceHeader::new(xorb_hash, chunk_count, total_bytes as usize),
            chunks: xorb_entries,
        });
        let file = MDBFileInfo {
            metadata: FileDataSequenceHeader::new(file_hash, 1, false, false),
            segments: vec![FileDataSequenceEntry::new(
                xorb_hash,
                total_bytes_u32,
                0,
                chunk_count,
            )],
            verification: Vec::new(),
            metadata_ext: None,
        };

        let mut writer = crab_xet::shard::ShardWriter::new();
        writer.add_xorb(xorb).expect("add xorb");
        writer.add_file(file).expect("add file");
        let (bytes, shard_hash) = writer.finalize().expect("finalize shard");
        (
            Bytes::from(bytes),
            shard_hash,
            xorb_bytes,
            xorb_hash,
            total_bytes,
        )
    }

