    #[derive(Debug)]
    struct GatedPutStore {
        inner: object_store::memory::InMemory,
        started: Arc<tokio::sync::Semaphore>,
        release: Arc<tokio::sync::Semaphore>,
        head_started: Option<Arc<tokio::sync::Semaphore>>,
        head_release: Option<Arc<tokio::sync::Semaphore>>,
    }

    impl std::fmt::Display for GatedPutStore {
        fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
            write!(f, "GatedPutStore")
        }
    }

    #[async_trait::async_trait]
    impl ObjectStore for GatedPutStore {
        async fn put_opts(
            &self,
            location: &Path,
            payload: PutPayload,
            opts: PutOptions,
        ) -> object_store::Result<PutResult> {
            self.started.add_permits(1);
            let permit =
                self.release
                    .acquire()
                    .await
                    .map_err(|error| object_store::Error::Generic {
                        store: "gated",
                        source: Box::new(error),
                    })?;
            permit.forget();
            self.inner.put_opts(location, payload, opts).await
        }

        async fn put_multipart_opts(
            &self,
            location: &Path,
            opts: PutMultipartOptions,
        ) -> object_store::Result<Box<dyn MultipartUpload>> {
            self.inner.put_multipart_opts(location, opts).await
        }

        async fn get_opts(
            &self,
            location: &Path,
            options: GetOptions,
        ) -> object_store::Result<GetResult> {
            if !options.head {
                return self.inner.get_opts(location, options).await;
            }
            if let (Some(started), Some(release)) = (&self.head_started, &self.head_release) {
                started.add_permits(1);
                let permit =
                    release
                        .acquire()
                        .await
                        .map_err(|error| object_store::Error::Generic {
                            store: "gated",
                            source: Box::new(error),
                        })?;
                permit.forget();
            }
            self.inner.get_opts(location, options).await
        }

        fn delete_stream(
            &self,
            locations: BoxStream<'static, object_store::Result<Path>>,
        ) -> BoxStream<'static, object_store::Result<Path>> {
            self.inner.delete_stream(locations)
        }

        fn list(
            &self,
            prefix: Option<&Path>,
        ) -> BoxStream<'static, object_store::Result<ObjectMeta>> {
            self.inner.list(prefix)
        }

        async fn list_with_delimiter(
            &self,
            prefix: Option<&Path>,
        ) -> object_store::Result<ListResult> {
            self.inner.list_with_delimiter(prefix).await
        }

        async fn copy_opts(
            &self,
            from: &Path,
            to: &Path,
            options: object_store::CopyOptions,
        ) -> object_store::Result<()> {
            self.inner.copy_opts(from, to, options).await
        }
    }

