    #[tokio::test]
    async fn upload_push_pack_file_body_stages_without_canonical_head() {
        let read_inner: Arc<dyn object_store::ObjectStore> = Arc::new(DenyHeadStore::new());
        let write_inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = crate::storage::store::Store::new(read_inner)
            .with_staging_write_store("repo/staging/push-1".to_owned(), write_inner.clone());
        let pack_path = ObjectPath::from("repo/packs/pack-a.pack");
        let staged_path = ObjectPath::from("repo/staging/push-1/objects/repo/packs/pack-a.pack");
        let body = Bytes::from_static(b"pack body");
        let mut pack_file = tempfile::NamedTempFile::new().unwrap();
        pack_file.write_all(&body).unwrap();
        pack_file.flush().unwrap();
        let pack_hash = blake3::hash(&body);

        let uploaded = upload_push_pack_file_body(
            &store,
            &pack_path,
            pack_file.path(),
            body.len() as u64,
            *pack_hash.as_bytes(),
            &CancellationToken::new(),
        )
        .await
        .unwrap();

        assert!(uploaded);
        let staged = write_inner
            .get(&staged_path)
            .await
            .unwrap()
            .bytes()
            .await
            .unwrap();
        assert_eq!(staged, body);
        assert_eq!(
            store.staged_writes()[0].canonical_key,
            "repo/packs/pack-a.pack"
        );
    }

    #[tokio::test]
    async fn upload_push_pack_file_body_uploads_large_file_once() {
        let inner = Arc::new(object_store::memory::InMemory::new());
        let store_inner: Arc<dyn object_store::ObjectStore> = inner.clone();
        let store = crate::storage::store::Store::new(store_inner);
        let pack_path = ObjectPath::from("repo/packs/pack-large.pack");
        let body = vec![0xab; PACK_MULTIPART_THRESHOLD_BYTES as usize + 1];
        let mut pack_file = tempfile::NamedTempFile::new().unwrap();
        pack_file.write_all(&body).unwrap();
        pack_file.flush().unwrap();
        let pack_hash = blake3::hash(&body);

        let uploaded = upload_push_pack_file_body(
            &store,
            &pack_path,
            pack_file.path(),
            body.len() as u64,
            *pack_hash.as_bytes(),
            &CancellationToken::new(),
        )
        .await
        .unwrap();
        let uploaded_again = upload_push_pack_file_body(
            &store,
            &pack_path,
            pack_file.path(),
            body.len() as u64,
            *pack_hash.as_bytes(),
            &CancellationToken::new(),
        )
        .await
        .unwrap();

        assert!(uploaded);
        assert!(!uploaded_again);
        let stored = inner.get(&pack_path).await.unwrap().bytes().await.unwrap();
        assert_eq!(stored.len(), body.len());
        assert_eq!(blake3::hash(&stored), pack_hash);
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn push_metadb_guard_uses_supplied_object_store() {
        use crab_metadata::key_codec::encode_committed_chunk_key;

        let inner = Arc::new(object_store::memory::InMemory::new());
        let store_inner: Arc<dyn object_store::ObjectStore> = inner.clone();
        let store = Store::new(store_inner);
        let router = StoreLayout::new(store.clone(), "repo-cache-metadb".to_owned());
        let (chunk_hash, _xorb_bytes, _xorb_hash, xorb_ref) =
            test_single_chunk_xorb(b"cache-aware metadb read");

        let seed_guard = build_push_metadb_guard(
            &store,
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        let chunk_store = seed_guard.chunk_index().await.expect("chunk index store");
        let receipts = test_committed_chunk_receipts(&[(chunk_hash, xorb_ref)]);
        let committed = &receipts[0].1;
        let mut txn = seed_guard.new_transaction().expect("transaction");
        chunk_store
            .save_committed_receipts(&mut txn, &receipts)
            .expect("seed committed chunk receipt");
        seed_guard.commit(txn).await.expect("seed chunk index");
        seed_guard.close().await.expect("close seed guard");

        let reads = Arc::new(Mutex::new(Vec::new()));
        let recording_store: Arc<dyn object_store::ObjectStore> = Arc::new(RecordingReadStore {
            inner,
            reads: Arc::clone(&reads),
        });
        let read_guard = build_push_metadb_guard_with_object_store(
            &store,
            Some(recording_store),
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            true,
        );
        let value = {
            let db = read_guard
                .chunk_index_db_handle()
                .await
                .expect("chunk index db");
            db.get(&encode_committed_chunk_key(
                &chunk_hash,
                &committed.receipt_id(),
            ))
            .await
            .expect("read seeded key")
        };
        read_guard.close().await.expect("close read guard");

        assert!(value.is_some());
        let seen = reads
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(
            seen.iter()
                .any(|path| path.contains(".crab/chunk_index_db/")),
            "expected chunk_index_db reads through supplied object store, saw {seen:?}"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn push_metadb_guard_routes_default_chunk_index_through_scoped_global_prefix() {
        let inner = Arc::new(object_store::memory::InMemory::new());
        let store_inner: Arc<dyn object_store::ObjectStore> = inner.clone();
        let repository_prefix = "environments/test/repositories/repo-1";
        let store = Store::new(store_inner).with_storage_scope(crab_types::storage::StorageScope {
            repo_prefix: repository_prefix.to_owned(),
            global_prefix: format!("{repository_prefix}/.crab"),
            source_repo: repository_prefix.to_owned(),
            scope_hash: "a".repeat(64),
        });
        let router = StoreLayout::new(store.clone(), "ignored-logical-prefix".to_owned());
        let reads = Arc::new(Mutex::new(Vec::new()));
        let recording_store: Arc<dyn object_store::ObjectStore> = Arc::new(RecordingReadStore {
            inner,
            reads: Arc::clone(&reads),
        });
        let guard = build_push_metadb_guard_with_object_store(
            &store,
            Some(recording_store),
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            true,
        );

        let error = guard
            .chunk_index_system_keys()
            .await
            .expect_err("fresh scoped chunk index should be uninitialized");
        assert!(error.is_metadb_read_only_uninitialized());
        guard.close().await.expect("close scoped metadb guard");

        let seen = reads
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(
            seen.iter().any(|path| path.starts_with(&format!(
                "{repository_prefix}/.crab/chunk_index_db/"
            ))),
            "expected scoped chunk_index_db reads, saw {seen:?}"
        );
        assert!(
            seen.iter()
                .all(|path| !path.starts_with(".crab/chunk_index_db/")),
            "unscoped chunk_index_db path escaped the managed grant: {seen:?}"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn push_metadb_writer_uses_supplied_cache_object_store_for_versioned_metadata() {
        let inner = Arc::new(object_store::memory::InMemory::new());
        let store_inner: Arc<dyn object_store::ObjectStore> = inner.clone();
        let store = Store::new(store_inner);
        let router = StoreLayout::new(store.clone(), "repo-origin-writer-metadb".to_owned());

        let seed_guard = build_push_metadb_guard(
            &store,
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        seed_guard
            .chunk_index_system_keys()
            .await
            .expect("seed chunk-index manifest");
        seed_guard.close().await.expect("close seed writer");

        let reads = Arc::new(Mutex::new(Vec::new()));
        let recording_store: Arc<dyn object_store::ObjectStore> = Arc::new(RecordingReadStore {
            inner: Arc::clone(&inner),
            reads: Arc::clone(&reads),
        });

        let guard = build_push_metadb_guard_with_object_store(
            &store,
            Some(recording_store),
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        guard
            .chunk_index_system_keys()
            .await
            .expect("writer should open through the supplied store");
        guard.close().await.expect("close writer guard");

        let seen = reads
            .lock()
            .unwrap_or_else(|poisoned| poisoned.into_inner());
        assert!(
            seen.iter()
                .any(|path| path.contains("chunk_index_db/manifest/")),
            "read-write MetaDB should route versioned metadata through the supplied store, saw {seen:?}"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn push_promotes_planning_reader_to_post_commit_writer() {
        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(inner);
        let router = StoreLayout::new(store.clone(), "repo-reader-promotion".to_owned());
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            Vec::new(),
            Some(store.clone()),
            None,
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );
        pipeline.install_metadb(build_push_metadb_guard_with_object_store(
            &store,
            None,
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            true,
        ));

        pipeline
            .promote_metadb_to_post_commit_writer()
            .await
            .expect("promote reader");
        let guard = pipeline.metadb.lock().await.take().expect("writer guard");
        let chunk_store = guard.chunk_index().await.expect("open writer");
        let mut txn = guard.new_transaction().expect("transaction");
        chunk_store.delete_legacy(&mut txn, &MerkleHash::from([3; 32]));
        guard.commit(txn).await.expect("writer transaction");
        guard.close().await.expect("close writer");
    }

