    #[test]
    fn exact_locator_basis_packs_every_unproven_object_individually() {
        let commit = gix_hash::ObjectId::from_hex(b"1111111111111111111111111111111111111111")
            .expect("commit oid");
        let tree = gix_hash::ObjectId::from_hex(b"2222222222222222222222222222222222222222")
            .expect("tree oid");
        let blob = gix_hash::ObjectId::from_hex(b"3333333333333333333333333333333333333333")
            .expect("blob oid");
        let candidates = vec![commit, tree, blob];
        let proven = HashSet::from([commit]);

        let missing = exact_missing_git_objects(&candidates, &proven);

        assert_eq!(missing, vec![tree, blob]);
    }

    fn make_update(force: bool, old_sha: Option<&str>) -> RefUpdate {
        RefUpdate {
            ref_name: "refs/heads/main".to_owned(),
            old_sha: old_sha.map(str::to_owned),
            new_sha: "new111".to_owned(),
            force,
        }
    }

