    fn make_spec(dst: &str) -> PushSpec {
        PushSpec {
            force: false,
            src: format!("{dst}"),
            dst: dst.to_owned(),
        }
    }

    fn make_delete_spec(dst: &str) -> PushSpec {
        PushSpec {
            force: false,
            src: String::new(),
            dst: dst.to_owned(),
        }
    }

    #[test]
    fn locked_manifest_noop_covers_equal_update_and_missing_delete() {
        let update = make_spec("refs/heads/main");
        let delete = make_delete_spec("refs/heads/already-gone");
        let sha = "a".repeat(40);
        let mut manifest = Manifest::default_for_repo("refs/heads/main");
        manifest.refs.insert(update.dst.clone(), sha.clone());
        let decisions = HashMap::from([
            (
                update.dst.clone(),
                RefUpdateDecision::Proceed { etag: None },
            ),
            (
                delete.dst.clone(),
                RefUpdateDecision::Proceed { etag: None },
            ),
        ]);
        let sha_map = HashMap::from([(update.src.clone(), sha)]);

        assert!(ref_edits_are_manifest_noop(
            &[update, delete],
            Some(&manifest),
            &decisions,
            &sha_map,
        ));
    }

    #[test]
    fn locked_manifest_noop_rejects_changed_update() {
        let update = make_spec("refs/heads/main");
        let mut manifest = Manifest::default_for_repo("refs/heads/main");
        manifest.refs.insert(update.dst.clone(), "a".repeat(40));
        let decisions = HashMap::from([(
            update.dst.clone(),
            RefUpdateDecision::Proceed { etag: None },
        )]);
        let sha_map = HashMap::from([(update.src.clone(), "b".repeat(40))]);

        assert!(!ref_edits_are_manifest_noop(
            &[update],
            Some(&manifest),
            &decisions,
            &sha_map,
        ));
    }

