    #[test]
    fn cas_retry_detects_delete_base_value_race() {
        let spec = make_delete_spec("refs/heads/main");
        let decisions =
            HashMap::from([(spec.dst.clone(), RefUpdateDecision::Proceed { etag: None })]);
        let mut base = Manifest::default_for_repo("refs/heads/main");
        base.refs.insert(spec.dst.clone(), "a".repeat(40));
        let mut current = base.clone();
        current.refs.insert(spec.dst.clone(), "b".repeat(40));

        let conflict = ref_base_conflicts(&[spec], &decisions, Some(&base), &current)
            .into_iter()
            .next()
            .expect("delete must compare its base value on retry");

        assert!(conflict.is_delete);
        assert_eq!(conflict.have, "b".repeat(40));
        assert_eq!(conflict.want, "a".repeat(40));
    }

