    #[tokio::test(flavor = "multi_thread")]
    async fn next_writer_repairs_publication_cancelled_at_active_marker() {
        let _guard = GitDirGuard::new();
        let cancel = CancellationToken::new();
        let armed = Arc::new(AtomicBool::new(false));
        let repo_prefix = "cancel-after-active-marker";
        let inner: Arc<dyn object_store::ObjectStore> = Arc::new(CancelAfterPutStore {
            inner: object_store::memory::InMemory::new(),
            cancel: cancel.clone(),
            armed: Arc::clone(&armed),
            exact_path: None,
            path_prefix: Some(format!("{repo_prefix}/refs/journal/active/")),
        });
        let store = Store::new(inner);
        let router = StoreLayout::new(store.clone(), repo_prefix.to_owned());
        let initial = Manifest::default_for_repo("refs/heads/main");
        create_manifest_with_etag(&store, &router, &initial)
            .await
            .expect("create initial manifest");
        armed.store(true, Ordering::SeqCst);

        let interrupted_pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![make_spec("refs/heads/main")],
            Some(store.clone()),
            None,
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            cancel.clone(),
            None,
        );
        let interrupted = Box::pin(interrupted_pipeline.execute()).await;

        assert!(
            cancel.is_cancelled(),
            "store fault must cancel at the marker"
        );
        assert_eq!(
            interrupted.outcomes.get("refs/heads/main"),
            Some(&RefPushOutcome::Ok),
            "the durable active marker is the successful ref boundary"
        );
        let interrupted_snapshot =
            crate::metadata::manifest::read_repository_snapshot(&store, &router)
                .await
                .expect("read interrupted journal state");
        assert_eq!(
            interrupted_snapshot.journal.refs.get("refs/heads/main"),
            Some(&crate::test::git_repo::TEST_GIT_REPO.commit_sha)
        );
        assert_eq!(interrupted_snapshot.journal.transactions.len(), 1);
        assert!(
            !crate::git::upload_pack_wire::snapshot_available(
                store.as_storage(),
                repo_prefix,
                &CancellationToken::new(),
            )
            .await,
            "protocol v2 must stay withheld while exact derived coverage is incomplete"
        );

        let restarted_pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![make_spec("refs/heads/dev")],
            Some(store.clone()),
            None,
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );
        let restarted = Box::pin(restarted_pipeline.execute()).await;

        assert_eq!(
            restarted.outcomes.get("refs/heads/dev"),
            Some(&RefPushOutcome::Ok)
        );
        let repaired = crate::metadata::manifest::read_repository_snapshot(&store, &router)
            .await
            .expect("read repaired repository state");
        assert!(repaired.journal.transactions.is_empty());
        assert!(repaired.manifest.refs.contains_key("refs/heads/main"));
        assert!(repaired.manifest.refs.contains_key("refs/heads/dev"));
        assert!(
            crate::git::upload_pack_wire::snapshot_available(
                store.as_storage(),
                repo_prefix,
                &CancellationToken::new(),
            )
            .await,
            "the next writer must recover visibility and exact locator coverage"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn upload_pack_repairs_locator_for_current_manifest_generation() {
        let _guard = GitDirGuard::new();
        let repo_prefix = "upload-pack-locator-repair";
        let (store, router) = test_store_router(repo_prefix);
        let initial = Manifest::default_for_repo("refs/heads/main");
        create_manifest_with_etag(&store, &router, &initial)
            .await
            .expect("create initial manifest");
        let pushed = PushPipeline::new(
            PushConfig::default(),
            vec![make_spec("refs/heads/main")],
            Some(store.clone()),
            None,
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        )
        .execute()
        .await;
        assert_eq!(
            pushed.outcomes.get("refs/heads/main"),
            Some(&RefPushOutcome::Ok)
        );

        let (mut manifest, etag) = read_manifest(&store, &router)
            .await
            .expect("read pushed manifest");
        let covered_generation = manifest.generation;
        let storage_router =
            crab_storage::StoreLayout::new(store.as_storage().clone(), repo_prefix.to_owned());
        let visibility = crab_metadata::git_visibility::read(
            store.as_storage(),
            &storage_router,
            manifest.generation,
            &manifest.pack_index_hash,
            &manifest.git_validation_digest,
        )
        .await
        .expect("read pushed visibility proof");
        manifest.generation = manifest.generation.saturating_add(1);
        manifest.seal_git_validation();
        let next_visibility = crab_metadata::git_visibility::GitVisibilityIndex::new(
            manifest.generation,
            manifest.pack_index_hash.clone(),
            manifest.git_validation_digest.clone(),
            visibility.refs,
        );
        crab_metadata::git_visibility::upload_if_absent(
            store.as_storage(),
            &storage_router,
            &next_visibility,
        )
        .await
        .expect("upload next visibility proof");
        write_manifest_cas(&store, &router, &manifest, &etag)
            .await
            .expect("advance manifest without locator publication");

        let stale = crab_metadata::git_object_locator::GitObjectLocatorSession::open(
            Arc::clone(store.inner()),
            repo_prefix,
        )
        .await
        .expect("open stale locator session");
        assert_eq!(
            stale.coverage().map(|coverage| coverage.generation),
            Some(covered_generation)
        );
        stale.close().await.expect("close stale locator session");

        let capability_store = store.as_storage().clone();
        let capability_prefix = repo_prefix.to_owned();
        let v2_ready = tokio::spawn(async move {
            crate::git::upload_pack_wire::snapshot_available(
                &capability_store,
                &capability_prefix,
                &CancellationToken::new(),
            )
            .await
        })
        .await
        .expect("join capability discovery");
        assert!(
            !v2_ready,
            "capability discovery must use complete-pack fetch while locator coverage lags"
        );
        let still_stale = crab_metadata::git_object_locator::GitObjectLocatorSession::open(
            Arc::clone(store.inner()),
            repo_prefix,
        )
        .await
        .expect("reopen stale locator session");
        assert_eq!(
            still_stale.coverage().map(|coverage| coverage.generation),
            Some(covered_generation),
            "capability discovery must not rebuild the locator"
        );
        still_stale
            .close()
            .await
            .expect("close unchanged locator session");

        let repository = crate::git::upload_pack_wire::open_repository(
            store.as_storage(),
            repo_prefix,
            &CancellationToken::new(),
        )
        .await
        .expect("upload-pack should repair current locator coverage");
        assert_eq!(repository.generation(), manifest.generation);
        repository
            .visibility_index(&CancellationToken::new())
            .await
            .expect("repaired repository should remain exactly authorized");

        let repaired = crab_metadata::git_object_locator::GitObjectLocatorSession::open(
            Arc::clone(store.inner()),
            repo_prefix,
        )
        .await
        .expect("open repaired locator session");
        assert_eq!(
            repaired.coverage().map(|coverage| coverage.generation),
            Some(manifest.generation)
        );
        repaired
            .close()
            .await
            .expect("close repaired locator session");
    }

