    #[tokio::test(flavor = "multi_thread")]
    async fn under_lock_refresh_rebases_plan_before_pack_work() {
        let _guard = GitDirGuard::new();
        let (store, router) = test_store_router("under-lock-refresh");
        let initial = Manifest::default_for_repo("refs/heads/main");
        create_manifest_with_etag(&store, &router, &initial)
            .await
            .expect("create initial manifest");
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![make_spec("refs/heads/main")],
            Some(store.clone()),
            None,
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );
        pipeline
            .read_base_manifest()
            .await
            .expect("read stale base");
        let sha_map = pipeline.resolve_src_ref_map().expect("resolve refs");
        let decisions = pipeline
            .evaluate_decisions_with_sha_map(&sha_map)
            .await
            .expect("initial decisions");
        *pipeline.planned_ref_decisions.lock().await = Some(decisions.clone());

        let (mut concurrent, etag) = read_manifest(&store, &router)
            .await
            .expect("read concurrent base");
        concurrent.generation += 1;
        concurrent.refs.insert(
            "refs/heads/unrelated".to_owned(),
            crate::test::git_repo::TEST_GIT_REPO.commit_sha.clone(),
        );
        concurrent.head = "refs/heads/unrelated".to_owned();
        concurrent.seal_git_validation();
        write_manifest_cas(&store, &router, &concurrent, &etag)
            .await
            .expect("commit unrelated ref");

        pipeline
            .acquire_push_lock()
            .await
            .expect("acquire ref lock");
        let refreshed = pipeline
            .refresh_base_bound_plan_after_lock(&sha_map, &decisions)
            .await
            .expect("refresh under lock");

        assert!(matches!(
            refreshed.get("refs/heads/main"),
            Some(RefUpdateDecision::Proceed { .. })
        ));
        assert_eq!(
            pipeline
                .base_manifest
                .lock()
                .await
                .as_ref()
                .map(|manifest| manifest.generation),
            Some(concurrent.generation)
        );
        assert!(pipeline.xorbs.lock().await.is_empty());
        assert!(pipeline.chunk_placement.lock().await.is_empty());
        assert!(pipeline.uploaded_packs.lock().await.is_empty());
        pipeline.stop_heartbeat_and_release_lock().await;
    }

    #[tokio::test]
    async fn direct_lock_acquisition_skips_preflight_rejected_refs() {
        let (store, router) = test_store_router("lock-proceeding-subset");
        let specs = vec![make_spec("refs/heads/main"), make_spec("refs/heads/dev")];
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            specs,
            Some(store),
            None,
            None,
            router.repo_prefix().to_owned(),
            router,
            None,
            CancellationToken::new(),
            None,
        );
        *pipeline.planned_ref_decisions.lock().await = Some(HashMap::from([
            (
                "refs/heads/main".to_owned(),
                RefUpdateDecision::Reject(PushRejectReason::DenyNonFastForward),
            ),
            (
                "refs/heads/dev".to_owned(),
                RefUpdateDecision::Proceed { etag: None },
            ),
        ]));

        pipeline.acquire_push_lock().await.expect("acquire subset");
        let state = pipeline.lock_state.lock().await;
        let leases = &state.as_ref().expect("lock state").leases;
        assert_eq!(leases.len(), 1);
        assert!(leases[0].lock.path().contains("refs/heads/dev"));
        assert!(!leases[0].lock.path().contains("refs/heads/main"));
        drop(state);
        pipeline.stop_heartbeat_and_release_lock().await;
    }

    #[tokio::test]
    async fn acquire_push_lock_leases_releases_partial_acquisition_on_contention() {
        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(inner);
        let blocker = PushLock::acquire_ref(
            store.inner(),
            "repo",
            "refs/heads/b",
            Duration::from_secs(60),
        )
        .await
        .unwrap();
        let specs = vec![make_spec("refs/heads/a"), make_spec("refs/heads/b")];

        let result = acquire_push_lock_leases(
            &store,
            "repo",
            &specs,
            &PushConfig::default(),
            &CancellationToken::new(),
        )
        .await;
        assert!(matches!(result, Err(CrabError::PushLockHeld { .. })));

        let lock = PushLock::acquire_ref(
            store.inner(),
            "repo",
            "refs/heads/a",
            Duration::from_secs(60),
        )
        .await
        .expect("partial acquisition must be released after later contention");
        lock.release().await.unwrap();
        blocker.release().await.unwrap();
    }

    #[tokio::test]
    async fn acquire_push_lock_leases_reclaims_visible_transaction_holder() {
        let (store, router) = test_store_router("committed-holder-recovery");
        create_manifest_with_etag(
            &store,
            &router,
            &Manifest::default_for_repo("refs/heads/main"),
        )
        .await
        .unwrap();
        let specs = vec![make_spec("refs/heads/main")];
        let config = PushConfig {
            heartbeat_interval: None,
            lock_ttl: Duration::from_secs(60),
            ..PushConfig::default()
        };
        let abandoned = acquire_push_lock_leases(
            &store,
            router.repo_prefix(),
            &specs,
            &config,
            &CancellationToken::new(),
        )
        .await
        .unwrap();
        let holder = abandoned[0].lock.holder().to_owned();
        let head =
            crate::metadata::manifest::read_ref_journal_head(&store, &router, "refs/heads/main")
                .await
                .unwrap();
        let transaction = crate::metadata::manifest::RefJournalTransaction::new(
            BTreeMap::from([("refs/heads/main".to_owned(), None)]),
            vec![crate::metadata::manifest::RefJournalEdit {
                ref_name: "refs/heads/main".to_owned(),
                old_oid: None,
                new_oid: Some("a".repeat(40)),
                peeled_oid: None,
                lock_holder: Some(holder),
                visibility_evidence_hash: None,
            }],
            None,
            Vec::new(),
            Vec::new(),
        )
        .unwrap();
        crate::metadata::manifest::commit_ref_journal_transaction(
            &store,
            &router,
            &transaction,
            &[head],
        )
        .await
        .unwrap();
        std::mem::forget(abandoned);

        let recovered = acquire_push_lock_leases(
            &store,
            router.repo_prefix(),
            &specs,
            &config,
            &CancellationToken::new(),
        )
        .await
        .expect("a visible transaction no longer needs its matching ref lease");

        release_push_lock_leases(recovered).await;
    }

