    #[test]
    fn push_pipeline_uses_common_git_dir_for_linked_worktree_objects() {
        let _git_env = crate::test::git_repo::CleanGitEnvGuard::new();

        fn run_git(cwd: &std::path::Path, args: &[&str]) {
            let out = std::process::Command::new("git")
                .args(args)
                .current_dir(cwd)
                .output()
                .expect("run git");
            assert!(
                out.status.success(),
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&out.stderr)
            );
        }

        fn git_output(cwd: &std::path::Path, args: &[&str]) -> String {
            let out = std::process::Command::new("git")
                .args(args)
                .current_dir(cwd)
                .output()
                .expect("run git");
            assert!(
                out.status.success(),
                "git {args:?} failed: {}",
                String::from_utf8_lossy(&out.stderr)
            );
            String::from_utf8(out.stdout)
                .expect("git stdout utf8")
                .trim()
                .to_owned()
        }

        let tmp = tempfile::tempdir().expect("tempdir");
        let repo = tmp.path().join("repo");
        let linked = tmp.path().join("linked");
        std::fs::create_dir(&repo).expect("repo dir");
        run_git(&repo, &["init", "--initial-branch=main"]);
        run_git(&repo, &["config", "user.email", "test@test.com"]);
        run_git(&repo, &["config", "user.name", "Test"]);
        run_git(&repo, &["config", "commit.gpgsign", "false"]);
        std::fs::write(repo.join("a.txt"), "one").expect("write file");
        run_git(&repo, &["add", "a.txt"]);
        run_git(&repo, &["commit", "-m", "one"]);
        run_git(
            &repo,
            &["worktree", "add", "-b", "feature", linked.to_str().unwrap()],
        );

        let raw_git_dir =
            std::path::PathBuf::from(git_output(&linked, &["rev-parse", "--git-dir"]));
        let per_worktree_git_dir = if raw_git_dir.is_absolute() {
            raw_git_dir
        } else {
            linked.join(raw_git_dir)
        };
        let common_git_dir = repo.join(".git").canonicalize().expect("common git dir");
        let mut config = PushConfig::default();
        config.git_dir = Some(per_worktree_git_dir);
        let pipeline = PushPipeline::new(
            config,
            vec![make_spec("refs/heads/feature")],
            None,
            None,
            None,
            String::new(),
            test_router(""),
            None,
            CancellationToken::new(),
            None,
        );

        assert_eq!(pipeline.common_git_dir().unwrap(), common_git_dir);
        assert_eq!(
            pipeline.objects_dir().unwrap(),
            common_git_dir.join("objects")
        );
    }

