    #[tokio::test(flavor = "multi_thread")]
    async fn cache_candidate_repairs_canonical_origin_before_dedup_acceptance() {
        use crate::core::config::{CacheConfig, ServiceAuth, ServiceMode};
        use crate::test::git_repo::CacheDirGuard;
        use axum::{
            Json, Router,
            routing::{get, post},
        };
        use crab_cache_store::CachingStore;
        use serde_json::json;

        let cache_tmp = tempfile::tempdir().expect("cache tempdir");
        let _cache_guard = CacheDirGuard::new(cache_tmp.path());
        let data = b"cache candidate copied to canonical origin".to_vec();
        let chunk_hash = compute_data_hash(&data);
        let (xorb_bytes, xorb_hash, refs) = test_xorb_with_chunks(&[(chunk_hash, data)]);
        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(Arc::clone(&inner));
        let router = StoreLayout::new(store.clone(), "repo-cache-repair".to_owned());
        let expected_repo = router.repo_prefix().to_owned();
        let object_route = format!("/v1/{}", router.xorb_path(&xorb_hash));
        let known = json!([{
            "index": 0,
            "xorb_hash": xorb_hash.hex(),
            "chunk_index": refs[0].chunk_index,
            "length": refs[0].uncompressed_size,
            "cache_verified": true,
        }]);
        let object_body = xorb_bytes.clone();
        let app = Router::new()
            .route(
                "/v1/dedup/query",
                post(move |Json(req): Json<serde_json::Value>| {
                    let expected_repo = expected_repo.clone();
                    let known = known.clone();
                    async move {
                        assert_eq!(req["repo_path"].as_str(), Some(expected_repo.as_str()));
                        Json(json!({ "known": known, "unknown": [] }))
                    }
                }),
            )
            .route(
                &object_route,
                get(move || {
                    let object_body = object_body.clone();
                    async move { object_body }
                }),
            );
        let listener = tokio::net::TcpListener::bind("127.0.0.1:0")
            .await
            .expect("bind cache service");
        let addr = listener.local_addr().expect("cache service addr");
        let (shutdown_tx, shutdown_rx) = tokio::sync::oneshot::channel::<()>();
        let server = tokio::spawn(async move {
            axum::serve(listener, app)
                .with_graceful_shutdown(async {
                    let _ = shutdown_rx.await;
                })
                .await
                .expect("cache service server");
        });
        let caching_store = CachingStore::new(
            store.clone(),
            &CacheConfig {
                service_url: Some(format!("http://{addr}")),
                service_mode: ServiceMode::CacheAndDedup,
                push_warming: false,
                chunk_cache_dir: None,
                service_auth: ServiceAuth::None,
                service_ca_cert: None,
                service_client_cert: None,
                service_client_key: None,
            },
        )
        .expect("caching store");
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            Some(store.clone()),
            Some(caching_store),
            None,
            router.repo_prefix().to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );

        let lookup = pipeline
            .lookup_cache_service_chunk_refs(&[chunk_hash])
            .await
            .expect("repair cache candidate");
        assert_eq!(lookup.get(&chunk_hash), Some(&refs[0]));
        let _ = shutdown_tx.send(());
        server.await.expect("cache service task");

        let (origin_body, _) = store
            .get_with_etag(&router.xorb_path(&xorb_hash))
            .await
            .expect("canonical origin survives cache shutdown");
        assert_eq!(origin_body, xorb_bytes);
    }

