    #[tokio::test(flavor = "multi_thread")]
    async fn push_start_gc_drift_wipes_local_chunk_index_cache() {
        use crate::test::git_repo::CacheDirGuard;
        use crab_metadata::persistent_chunk_index::PersistentChunkIndex;

        let cache_tmp = tempfile::tempdir().expect("tempdir");
        let _cache_guard = CacheDirGuard::new(cache_tmp.path());

        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(inner);
        let router = StoreLayout::new(store.clone(), "repo-gc-drift".to_owned());
        let cache_path =
            crate::cache::chunk_index_cache_path(cache_tmp.path(), &store.bucket_identity());

        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            Some(store.clone()),
            None,
            None,
            "repo-gc-drift".to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );

        let guard = build_push_metadb_guard(
            &store,
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        let chunk_store = guard.chunk_index().await.expect("chunk index store");
        let stale_shard = MerkleHash::from([0xCAFE, 0xDAD, 0x5150, 0x1111]);
        let stale_chunk = MerkleHash::from([0xC0FFEE, 0x5150, 0x2222, 0x3333]);
        let stale_ref = XorbRef {
            xorb_hash: MerkleHash::from([0xDEAD, 0xBEEF, 0x4444, 0x5555]),
            chunk_index: 7,
            uncompressed_size: 4096,
        };
        chunk_store
            .warm_local_shard(stale_shard, &[(stale_chunk, stale_ref)])
            .await
            .expect("warm stale local cache");
        assert_eq!(
            chunk_store
                .get(&stale_chunk)
                .await
                .expect("pre-drift local hit"),
            Some(stale_ref)
        );

        for _ in 0..4 {
            guard
                .bump_gc_generation()
                .await
                .expect("bump gc generation");
        }
        pipeline.install_metadb(guard);

        pipeline.check_chunk_index_cache_gc_drift().await;

        assert_eq!(
            chunk_store
                .get(&stale_chunk)
                .await
                .expect("post-drift lookup"),
            None,
            "push-start drift check must clear the in-memory tier"
        );
        let persistent = PersistentChunkIndex::open_shared(&cache_path).expect("open sqlite");
        assert_eq!(
            persistent.get(&stale_chunk).expect("persistent lookup"),
            None,
            "push-start drift check must clear the SQLite tier"
        );
        assert!(
            !persistent.has_shard(&stale_shard).expect("shard marker"),
            "clearing SQLite must also drop stale shard markers"
        );

        pipeline.close_metadb().await;
    }

