    #[tokio::test(flavor = "multi_thread")]
    async fn verified_global_lookup_ignores_missing_xorb_hits() {
        use crate::test::git_repo::CacheDirGuard;

        let cache_tmp = tempfile::tempdir().expect("tempdir");
        let _cache_guard = CacheDirGuard::new(cache_tmp.path());

        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(inner);
        let router = StoreLayout::new(store.clone(), "repo-stale-global".to_owned());
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            Some(store.clone()),
            None,
            None,
            "repo-stale-global".to_owned(),
            router.clone(),
            None,
            CancellationToken::new(),
            None,
        );

        let missing_xorb = MerkleHash::from([0xBAD, 0x610BA1, 0xC0DE, 0x404]);
        let chunk_hashes: Vec<MerkleHash> = (0..=GLOBAL_CHUNK_LOOKUP_REMOTE_BATCH_SIZE / 2)
            .map(|idx| MerkleHash::from([idx as u64, 0x5151, 0xABCD, 0x1234]))
            .collect();
        let global_entries: Vec<(MerkleHash, XorbRef)> = chunk_hashes
            .iter()
            .enumerate()
            .map(|(idx, chunk_hash)| {
                (
                    *chunk_hash,
                    XorbRef {
                        xorb_hash: missing_xorb,
                        chunk_index: idx as u32,
                        uncompressed_size: 4096,
                    },
                )
            })
            .collect();

        let guard = build_push_metadb_guard(
            &store,
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        let chunk_store = guard.chunk_index().await.expect("chunk index store");
        let mut txn = guard.new_transaction().expect("transaction");
        chunk_store
            .save_committed_receipts(&mut txn, &test_committed_chunk_receipts(&global_entries))
            .expect("seed committed chunk receipts");
        let receipt = guard.commit(txn).await.expect("seed global chunk index");
        assert_eq!(
            receipt.chunk_ops_written as usize,
            expected_test_committed_receipt_ops(&global_entries)
        );
        pipeline.install_metadb(guard);

        let lookup = pipeline
            .lookup_verified_global_chunk_refs(&chunk_hashes)
            .await
            .expect("lookup global refs");
        assert!(
            lookup.refs.is_empty(),
            "missing global xorbs must not be treated as verified refs"
        );
        assert_eq!(lookup.stale_hits, chunk_hashes.len());

        pipeline.close_metadb().await;
    }

