    #[tokio::test(flavor = "multi_thread")]
    async fn verify_remote_xorb_refs_caps_payload_proof_concurrency() {
        let current_range_gets = Arc::new(AtomicUsize::new(0));
        let max_range_gets = Arc::new(AtomicUsize::new(0));
        let store = Store::new(Arc::new(InFlightRangeStore::new(
            Arc::clone(&current_range_gets),
            Arc::clone(&max_range_gets),
            std::time::Duration::from_millis(25),
        )));
        let router = StoreLayout::new(store.clone(), "repo-step4-payload-concurrency".to_owned());
        let xorb_count = REMOTE_XORB_PROOF_PAYLOAD_CONCURRENCY + 8;
        let mut refs = HashMap::new();
        let mut indexes = HashMap::new();
        for idx in 0..xorb_count {
            let data = format!("remote-proof-concurrency-chunk-{idx}").into_bytes();
            let (chunk_hash, xorb_bytes, xorb_hash, xorb_ref) = test_single_chunk_xorb(&data);
            let path = router.xorb_path(&xorb_hash);
            store
                .put(&path, xorb_bytes)
                .await
                .expect("seed xorb object");
            let object_size = store.head(&path).await.expect("head xorb").size;
            let index = remote_xorb_index(&store, &path, object_size)
                .await
                .expect("index xorb");
            indexes.insert(xorb_hash, index);
            refs.insert(chunk_hash, xorb_ref);
        }

        current_range_gets.store(0, Ordering::SeqCst);
        max_range_gets.store(0, Ordering::SeqCst);
        let pipeline = PushPipeline::new(
            PushConfig {
                head_check_concurrency: xorb_count,
                ..PushConfig::default()
            },
            vec![],
            Some(store.clone()),
            None,
            None,
            "repo-step4-payload-concurrency".to_owned(),
            router,
            None,
            CancellationToken::new(),
            None,
        );
        pipeline
            .remote_xorb_index_cache
            .lock()
            .await
            .extend(indexes);

        let verified = pipeline
            .verify_remote_xorb_refs(&refs)
            .await
            .expect("verify remote refs");

        assert_eq!(verified, refs);
        let max_ranges = max_range_gets.load(Ordering::SeqCst);
        assert!(
            max_ranges <= REMOTE_XORB_PROOF_PAYLOAD_CONCURRENCY,
            "payload proof range reads exceeded cap: {max_ranges}"
        );
        assert!(
            max_ranges > 1,
            "test should exercise concurrent payload proof range reads"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
