    #[tokio::test(flavor = "multi_thread")]
    async fn upload_xorbs_drains_sibling_uploads_after_first_error() {
        use crate::storage::retry::RetryPolicy;

        let fail_hash = MerkleHash::from([1_u64, 1, 1, 1]);
        let ok_hash_a = MerkleHash::from([2_u64, 2, 2, 2]);
        let ok_hash_b = MerkleHash::from([3_u64, 3, 3, 3]);
        let fail_path = canonical_global_content_path("xorbs", &fail_hash.hex());
        let completed_puts = Arc::new(AtomicUsize::new(0));
        let delay = std::time::Duration::from_millis(75);
        let inner: Arc<dyn object_store::ObjectStore> = Arc::new(DelayedFailurePutStore::new(
            fail_path.clone(),
            delay,
            Arc::clone(&completed_puts),
        ));
        let store = Store::with_retry(
            inner,
            RetryPolicy {
                max_attempts: 1,
                base: std::time::Duration::ZERO,
                cap: std::time::Duration::ZERO,
            },
        );
        let router = StoreLayout::new(store.clone(), "repo-upload-drain".to_owned());
        let pipeline = PushPipeline::new(
            PushConfig {
                upload_concurrency: 3,
                ..PushConfig::default()
            },
            vec![],
            Some(store),
            None,
            None,
            "repo-upload-drain".to_owned(),
            router,
            None,
            CancellationToken::new(),
            None,
        );

        *pipeline.xorbs.lock().await = vec![
            PackedXorb::from_result(XorbResult {
                bytes: Bytes::from_static(b"fail"),
                hash: fail_hash,
                payload_digest: [9; 32],
                placements: Vec::new(),
            })
            .await
            .expect("pack fail xorb"),
            PackedXorb::from_result(XorbResult {
                bytes: Bytes::from_static(b"ok-a"),
                hash: ok_hash_a,
                payload_digest: [9; 32],
                placements: Vec::new(),
            })
            .await
            .expect("pack ok-a xorb"),
            PackedXorb::from_result(XorbResult {
                bytes: Bytes::from_static(b"ok-b"),
                hash: ok_hash_b,
                payload_digest: [9; 32],
                placements: Vec::new(),
            })
            .await
            .expect("pack ok-b xorb"),
        ];

        let start = std::time::Instant::now();
        let err = pipeline
            .upload_xorbs()
            .await
            .expect_err("failed xorb should fail the upload step");

        assert!(
            matches!(err, CrabError::NotFound { ref path } if path == &fail_path.to_string()),
            "expected injected NotFound, got {err:?}"
        );
        assert!(
            start.elapsed() >= delay,
            "upload_xorbs must wait for sibling upload tasks before returning"
        );
        assert_eq!(
            completed_puts.load(Ordering::SeqCst),
            2,
            "non-failing sibling uploads must finish before the error returns"
        );
        assert!(
            pipeline.uploaded_xorbs.lock().await.is_empty(),
            "failed push must not retain xorb bytes for cache warming"
        );
    }

    #[tokio::test(flavor = "multi_thread")]
    async fn upload_xorbs_streams_disk_backed_payloads() {
        use crab_xet::xorb::builder::{CompressionPolicy, FixedCompression};

        let mut data = vec![0u8; XORB_MULTIPART_THRESHOLD + 1024 * 1024];
        let mut state = 0x1234_5678_u64;
        for byte in &mut data {
            state ^= state << 13;
            state ^= state >> 7;
            state ^= state << 17;
            *byte = state as u8;
        }
        let chunk = Chunk::new(Bytes::from(data));
        let policy: Arc<dyn CompressionPolicy> =
            Arc::new(FixedCompression::new(CompressionScheme::None));
        let mut builder = XorbBuilder::with_policy(policy);
        builder.push(&chunk, RunId(0)).expect("push chunk");
        let mut results = builder.finalize().expect("finalize xorb");
        let result = results.pop().expect("one xorb");
        let expected = result.bytes.clone();
        assert!(
            expected.len() > XORB_MULTIPART_THRESHOLD,
            "test xorb must take the multipart upload path"
        );

        let spill_tmp = tempfile::tempdir().expect("spill tempdir");
        let packed =
            PackedXorb::from_result_with_memory_limit(result, 0, Some(spill_tmp.path()), None)
                .await
                .expect("spill packed xorb");
        assert!(packed.is_spilled(), "test must use a disk-backed payload");
        let xorb_hash = packed.hash;

        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let store = Store::new(Arc::clone(&inner));
        let router = StoreLayout::new(store.clone(), "repo-upload-file-backed".to_owned());
        let path = router.xorb_path(&xorb_hash);
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            Some(store),
            None,
            None,
            "repo-upload-file-backed".to_owned(),
            router,
            None,
            CancellationToken::new(),
            None,
        );
        *pipeline.xorbs.lock().await = vec![packed];

        pipeline.upload_xorbs().await.expect("upload xorbs");

        let uploaded = inner.get(&path).await.unwrap().bytes().await.unwrap();
        assert_eq!(uploaded, expected);
        assert_eq!(
            pipeline.uploaded_xorbs.lock().await.len(),
            1,
            "uploaded payload should be retained for cache warming"
        );
    }

