    #[tokio::test(flavor = "multi_thread")]
    async fn metadb_commit_failure_aborts_before_refs_advance() {
        use crate::metadata::metadb::{MetaDb, MetaDbConfig, MetaDbGuard};

        let repo_prefix = "repo-metadb-readonly";
        let inner: Arc<dyn object_store::ObjectStore> =
            Arc::new(object_store::memory::InMemory::new());
        let cache_dir = tempfile::tempdir().expect("tempdir");
        let cache_path = cache_dir.path().join("chunk-index.sqlite");

        {
            let config = MetaDbConfig {
                local_chunk_index_path: cache_path.clone(),
                ..MetaDbConfig::for_repo(repo_prefix)
            };
            let metadb = MetaDb::new(Arc::clone(&inner), repo_prefix.to_owned(), config);
            let file_store = metadb.file_index().await.expect("seed file_index");
            let chunk_store = metadb.chunk_index().await.expect("seed chunk_index");
            let mut txn = metadb.new_transaction();
            file_store.save_legacy(
                &mut txn,
                &MerkleHash::from([10_u64, 0, 0, 0]),
                &MerkleHash::from([11_u64, 0, 0, 0]),
            );
            let committed = test_committed_chunk_receipts(&[(
                MerkleHash::from([12_u64, 0, 0, 0]),
                XorbRef {
                    xorb_hash: MerkleHash::from([13_u64, 0, 0, 0]),
                    chunk_index: 0,
                    uncompressed_size: 1,
                },
            )]);
            chunk_store
                .save_committed_receipts(&mut txn, &committed)
                .expect("seed committed chunk receipt");
            metadb.commit(txn).await.expect("seed commit");
            metadb.close_all().await.expect("seed close");
        }

        let store = Store::new(Arc::clone(&inner));
        let router = StoreLayout::new(store.clone(), repo_prefix.to_owned());
        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            Some(store),
            None,
            None,
            repo_prefix.to_owned(),
            router,
            None,
            CancellationToken::new(),
            None,
        );

        let config = MetaDbConfig {
            local_chunk_index_path: cache_path,
            read_only: true,
            ..MetaDbConfig::for_repo(repo_prefix)
        };
        let guard = MetaDbGuard::new(MetaDb::new(
            Arc::clone(&inner),
            repo_prefix.to_owned(),
            config,
        ));
        pipeline.install_metadb(guard);
        let chunk_hash = MerkleHash::from([20_u64, 0, 0, 0]);
        let placement = ChunkPlacement {
            chunk_hash,
            xorb_hash: MerkleHash::from([21_u64, 0, 0, 0]),
            chunk_index: 0,
            uncompressed_size: 1,
        };
        pipeline
            .chunk_placement
            .lock()
            .await
            .insert(chunk_hash, placement.clone());

        let file_hash = MerkleHash::from([30_u64, 0, 0, 0]);
        let shard_hash = MerkleHash::from([31_u64, 0, 0, 0]);
        install_test_metadb_commit_dependencies(
            &pipeline,
            file_hash,
            &[(chunk_hash, 1)],
            &[placement],
        )
        .await;
        let err = pipeline
            .commit_metadb_and_warm_cache(&[(file_hash, 0)], &[shard_hash], test_committed_anchor())
            .await
            .expect_err("read-only metadb commit must abort push");

        match err {
            CrabError::MetaDb(crate::core::error::MetaDbError::ReadOnly { op, .. }) => {
                assert_eq!(op, "commit");
            }
            other => panic!("expected MetaDbError::ReadOnly, got {other:?}"),
        }
        assert!(
            pipeline.metadb.lock().await.is_some(),
            "MetaDb guard must be restored after commit failure"
        );
        pipeline.close_metadb().await;
    }

