        let (shard_bytes, shard_hash, xorb_bytes, xorb_hash) = test_shard_with_file(file_hash, 31);

        let seed_guard = build_push_metadb_guard_with_object_store(
            &store,
            Some(Arc::clone(&metadata_cache)),
            &router,
            None,
            &crate::core::config::MetaDbTomlConfig::default(),
            false,
        );
        let file_store = seed_guard.file_index().await.expect("file index store");
        let mut txn = seed_guard.new_transaction().expect("transaction");
        file_store.save_legacy(&mut txn, &file_hash, &shard_hash);
        seed_guard
            .commit(txn)
            .await
            .expect("seed cache-only file-index");
