    #[tokio::test(flavor = "multi_thread")]
    async fn zero_byte_pointer_with_no_chunks_builds_empty_file_metadata() {
        use crate::git::walk::PointerBlob;
        use crate::test::git_repo::CacheDirGuard;
        use crab_staging::{StagingArea, StagingAreaReadOnly};
        use crab_xet::shard::ShardReader;

        let cache_tmp = tempfile::tempdir().expect("cache tempdir");
        let _cache_guard = CacheDirGuard::new(cache_tmp.path());

        let tmp = tempfile::tempdir().expect("tempdir");
        let file_hash = MerkleHash::from(*blake3::hash(&[]).as_bytes());
        {
            let staging = StagingArea::open(tmp.path().to_path_buf())
                .await
                .expect("open staging rw");
            staging
                .pre_register_file(&file_hash, 0)
                .expect("pre-register zero-byte file");
            publish_recipe_for_test(&staging, "zero-byte-file", file_hash, 0, &[]);
            staging.close().await.expect("close");
        }
        let ro = Arc::new(
            StagingAreaReadOnly::open(tmp.path().to_path_buf())
                .await
                .expect("open ro"),
        );

        let pipeline = PushPipeline::new(
            PushConfig::default(),
            vec![],
            None,
            None,
            Some(Arc::clone(&ro)),
            "test-repo".to_owned(),
            test_router("test-repo"),
            None,
            CancellationToken::new(),
            None,
        );
        pipeline.pointers.lock().await.push(PointerBlob {
            oid: [1u8; 20],
            file_hash: file_hash.into(),
            size: 0,
        });

        pipeline
            .lookup_staging()
            .await
            .expect("zero-byte pointer needs no chunk rows");
        assert!(
            pipeline.remote_only_pointers.lock().await.is_empty(),
            "zero-byte file should be published as local metadata, not remote-only"
        );

        pipeline
            .build_shard()
            .await
            .expect("zero-byte file metadata shard");

        let shard_results = pipeline.shard_results.lock().await;
        assert_eq!(shard_results.len(), 1);
        let (bytes, shard_hash) = &shard_results[0];
        let reader = ShardReader::from_bytes(Bytes::from(bytes.clone()), *shard_hash);
        let file_info = reader
            .get_file_info(&file_hash)
            .expect("read shard file info")
            .expect("zero-byte file must be in the shard");
        assert!(file_info.segments.is_empty());
        assert_eq!(file_info.file_size(), 0);

        let file_shard_index = pipeline.file_shard_index.lock().await;
        assert_eq!(file_shard_index.get(&file_hash), Some(&0));
    }

